func (t *UserPersonalization) CreateTableWithDBType(db database.Executor, company string, dbType database.DBType) error {
	tableName := UserPersonalizationTableName
	var schema string
	if dbType == database.DBTypePostgres {
		schema = GetUserPersonalizationPostgresTableSchema()
	} else {
		schema = GetUserPersonalizationTableSchema()
	}

	createSQL := fmt.Sprintf(`CREATE TABLE IF NOT EXISTS "%s" (%s)`, tableName, schema)
	_, err := db.Exec(createSQL)
	if err != nil {
		return fmt.Errorf("failed to create User_Personalization table: %w", err)
	}

	// Indexes (Keys) and SIFT totals
	return t.SyncKeys(db, company, dbType)
}

// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *UserPersonalization) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := UserPersonalizationTableName
	siftCompany := ""
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (user_id)`,
		"User_Personalization$Primary", tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	var keys []sift.Key
	for _, spec := range userPersonalizationSIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, UserPersonalizationTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, UserPersonalizationTableName, keys)
}

// userPersonalizationSIFTSpecs are the table's keys with sum_index_fields
func userPersonalizationSIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *UserPersonalization) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := UserPersonalizationTableName, ""
	var results []sift.VerifyResult
	for _, spec := range userPersonalizationSIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, UserPersonalizationTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: UserPersonalizationTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, UserPersonalizationTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

