func (t *UserPersonalization) Get(primaryKey interface{}) bool {
	// A composite primary key (map[string]interface{}, values also as text)
	if pkMap, ok := primaryKey.(map[string]interface{}); ok {
		key := userPersonalizationFields.KeyFromMap(pkMap)
		return t.GetByPK(key[0].(types.Code))
	}
	// The primary key itself (a table with one primary key field)
	if key, ok := userPersonalizationFields.KeyFromValue(primaryKey); ok {
		return t.GetByPK([]any{key}[0].(types.Code))
	}

	fmt.Printf("Error: Invalid primary key type for User_Personalization.Get: %T (use map for composite keys)\n", primaryKey)
	return false
}

