// CalcSums sets each of the decimal or integer fields to its total over the records matching
// the current filters (CalcSums)
func (t *UserPersonalization) CalcSums(fieldNames ...string) error {
	tableName := UserPersonalizationTableName
	where, args := t.buildWhereClause()
	for _, name := range fieldNames {
		var column string
		switch strings.ToLower(name) {
		case "wallpaper_opacity":
			column = "wallpaper_opacity"
		case "wallpaper_blur":
			column = "wallpaper_blur"
		case "panel_opacity":
			column = "panel_opacity"
		case "font_size":
			column = "font_size"
		default:
			return fmt.Errorf("CalcSums: %s is not a decimal or integer field of User_Personalization", name)
		}
		query := t.convertPlaceholders(fmt.Sprintf(`SELECT CAST(COALESCE(SUM(%s), 0) AS TEXT) FROM "%s" WHERE %s`, column, tableName, where), len(args))
		var total string
		if err := t.exec().QueryRow(query, args...).Scan(&total); err != nil {
			return fmt.Errorf("CalcSums User_Personalization.%s: %w", column, err)
		}
		switch column {
		case "wallpaper_opacity":
			f, err := strconv.ParseFloat(total, 64)
			if err != nil {
				return fmt.Errorf("CalcSums User_Personalization.%s: %w", column, err)
			}
			t.Wallpaper_opacity = int(f)
		case "wallpaper_blur":
			f, err := strconv.ParseFloat(total, 64)
			if err != nil {
				return fmt.Errorf("CalcSums User_Personalization.%s: %w", column, err)
			}
			t.Wallpaper_blur = int(f)
		case "panel_opacity":
			f, err := strconv.ParseFloat(total, 64)
			if err != nil {
				return fmt.Errorf("CalcSums User_Personalization.%s: %w", column, err)
			}
			t.Panel_opacity = int(f)
		case "font_size":
			f, err := strconv.ParseFloat(total, 64)
			if err != nil {
				return fmt.Errorf("CalcSums User_Personalization.%s: %w", column, err)
			}
			t.Font_size = int(f)
		}
	}
	return nil
}

